  "setup": {"back": "Back", "next": "Next", "skip": "Skip for now", "skip_all": "Skip setup", "progress": "{n} of {total}", "done": {"button": "Open the dashboard", "title": "You're set up", "summary": {"one": "1 device tracked.", "other": "{n} devices tracked."}, "incomplete_title": "Nothing connected yet", "incomplete_summary": "You haven't signed in or tracked anything yet. Connect an account to start seeing locations.", "go_to_signin": "Go to Sign-in", "no_account": "No account is connected yet.", "polling": "Find+ checks for new locations about every {n} minutes.", "not_polling": "Find+ is not checking for locations yet, because no device is tracked.", "groups": {"one": "1 group.", "other": "{n} groups."}, "places": {"one": "1 place.", "other": "{n} places."}, "lock_on": "App lock is on.", "lock_off": "App lock is off.", "where_title": "Where to find things", "where_native": "The F+ icon in your menu bar shows Find+'s status. Choose Open Dashboard to see the map.", "where_web": "Open Find+ any time at {url}.", "where_settings": "Settings (under More on a phone) holds sign-in, polling, app lock and Run setup again."}, "welcome": {"title": "See where your trackers are, privately", "body": "Find+ tracks your Google Find Hub and Apple Find My devices. Your location history stays on this machine. Map tiles always load from OpenStreetMap. Anything else leaves only when you turn it on: signing in to Google or Apple, address search, and any alert channel you connect (Telegram, WhatsApp or a webhook).", "start": "Get started", "rerun": "Find+ is already set up. Changes you make here apply straight away, and skipping a step undoes nothing.", "point_1": "Reads locations from your Google Find Hub and Apple Find My accounts.", "point_2": "Keeps the history on this computer.", "point_3": "Takes about three minutes. Only signing in is needed; every other step is optional."}, "signin": {"title": "Connect your accounts", "lead": "Connect Google, Apple, or both, so Find+ can read where your trackers are. Next you'll choose which devices to follow. Not ready? Skip this and connect later in Settings.", "not_signed_in": "Not signed in yet.", "signed_in_as": "Connected: {accounts}.", "locked": "Google is connected, but its encrypted locations are still locked. Unlock them below, or skip and do it later in Settings.", "nextHint": "Connect at least one account to go on, or choose Skip to do it later."}, "devices": {"title": "Choose what to track", "empty": "No devices found yet. Refresh once you've added a tracker.", "label_placeholder": "Your name for this tracker", "refresh": "Refresh from your providers", "edit": "Edit", "track": "Track", "trackFor": "Track {name}", "labelFor": "Label for {name}", "confirm_none_tracked": "Track nothing? Find+ will not poll any tracker until you come back and tick one.", "refresh_no_provider": "No provider is signed in yet. Go back to Sign-in to connect one, then refresh.", "load_failed": "Could not load your devices right now. Try again.", "lead": "Tick the devices Find+ should follow. Find+ asks Google and Apple for every tracked device on each check, so tracking more devices means more requests and more polling. Track only what you need.", "no_location": "Some devices are listed but may never show a location, such as tags that are switched off, have not been seen by a nearby phone, or whose locations are still locked. They stay in the list and reach the map once they report.", "selected": {"one": "{n} of {total} selected", "other": "{n} of {total} selected"}, "loading": "Looking for your devices…", "empty_signed_out": "No devices yet, because no account is connected. Go back and sign in, or skip this step and do it later.", "go_signin": "Back to sign-in"}, "groups": {"title": "Groups (optional)", "lead": "Combine devices into a group to see them together on the map and set alerts for the whole group.", "name_placeholder": "Group name", "add": "Add", "no_devices": "No tracked devices to add yet. Go back to Devices to track one first.", "skip_hint": "Most people skip this. You can make groups any time from the Groups tab."}, "places": {"title": "Places (optional)", "add": "Add a place", "lead": "A place is a circle on the map, such as Home or Work. Find+ records when a tracker arrives or leaves, and alert rules can use it.", "empty": "No places yet. Add one now, or later from the Places tab.", "alertsOn": "arrival alerts on", "alertsOff": "no alerts yet"}, "notifications": {"title": "Notifications (optional)", "telegram": "Telegram", "webhook": "Webhook", "whatsapp": "WhatsApp", "native": "Notifications", "connect": "Connect", "configure_later": "Configure from the Alerts tab after finishing setup.", "enable": "Enable notifications", "permission_granted": "Notifications are on.", "permission_denied": "Notifications are off. You can turn them on in your system settings.", "token_placeholder": "Bot token from @BotFather", "enter_token": "Enter your bot token first.", "waiting": "Send your bot a message now. Waiting for it...", "connected": "Connected to {chat}.", "already_connected": "Telegram is already connected.", "telegram_help_token": "Create a bot with @BotFather on Telegram and paste its token here.", "telegram_help_chat": "Then send your new bot any message and press Connect. Find+ reads the chat id from that message.", "telegram_connect_first": "Connect the bot above first.", "telegram_targets_placeholder": "Chat IDs or @usernames", "finish_and_open_alerts": "Finish setup and open Alerts", "lead": "Alert channels tell you when a tracker arrives, leaves or goes quiet. Everything below is off until you set it up, and you can do all of it later from the Alerts tab."}, "applock": {"title": "App lock (optional)", "pin": "New PIN", "pin_confirm": "Confirm PIN", "set": "Set PIN", "set_ok": "PIN set. The app lock is on.", "lead": "Ask for a PIN before Find+ shows your location history. Use at least 6 characters.", "on": "App lock is already on. Change or remove the PIN in Settings, under App lock.", "after": "Once a PIN is set, Find+ asks for it after it has been idle for a while."}, "rerun": "Run setup again", "banner": {"unfinished": "Setup isn't finished.", "resume": "Resume setup", "dismiss": "Dismiss"}, "offline": "You appear to be offline. Find+ keeps what you've typed, but signing in and refreshing need a connection.", "close_rerun": "Close setup", "progress_named": "Step {n} of {total}: {name}", "step_names": {"welcome": "Welcome", "signin": "Connect your accounts", "devices": "Choose devices", "groups": "Groups", "places": "Places", "notifications": "Notifications", "applock": "App lock", "done": "Summary"}},
